from pathlib import Path

p=Path('desktop-client/src/main/java/com/example/desktop/ElectricalWorkbenchNativeApp.java')
s=p.read_text()
old='''        Label version=new Label("v"+updater.currentVersion());version.setStyle("-fx-text-fill:#a5f3fc;-fx-font-size:11px;");Region push=new Region();HBox.setHgrow(push,Priority.ALWAYS);\n        Button update=new Button("Checking updates…");update.setVisible(false);update.setManaged(false);update.setStyle("-fx-background-color:#16a34a;-fx-text-fill:white;-fx-font-weight:bold;-fx-background-radius:8;-fx-padding:7 10;");\n'''
new='''        Label version=new Label("Installed v"+updater.currentVersion());version.setStyle("-fx-text-fill:#a5f3fc;-fx-font-size:12px;-fx-font-weight:bold;");Region push=new Region();HBox.setHgrow(push,Priority.ALWAYS);\n        Button update=new Button("Check for Updates");update.setVisible(true);update.setManaged(true);update.setStyle("-fx-background-color:#16a34a;-fx-text-fill:white;-fx-font-weight:bold;-fx-background-radius:8;-fx-padding:7 10;");\n        update.setOnAction(e->checkForUpdates(update,true));\n'''
if old not in s: raise SystemExit('top-bar updater block not found')
s=s.replace(old,new)
s=s.replace('top.getChildren().addAll(brand,version,push,update,cloud,logout);root.setTop(top);checkForUpdates(update);','top.getChildren().addAll(brand,version,push,update,cloud,logout);root.setTop(top);checkForUpdates(update,false);')
old_method='''    private void checkForUpdates(Button button){CompletableFuture.supplyAsync(()->{try{return updater.check();}catch(Exception ex){return null;}}).thenAccept(info->Platform.runLater(()->{if(info==null||!info.updateAvailable())return;button.setText("Update v"+info.latestVersion());button.setVisible(true);button.setManaged(true);button.setOnAction(e->installUpdate(info,button));}));}\n'''
new_method='''    private void checkForUpdates(Button button){checkForUpdates(button,false);}\n    private void checkForUpdates(Button button,boolean manual){\n        button.setDisable(true);button.setText("Checking updates…");\n        CompletableFuture.supplyAsync(()->{try{return updater.check();}catch(Exception ex){throw new RuntimeException(ex);}})\n            .whenComplete((info,err)->Platform.runLater(()->{\n                button.setDisable(false);\n                if(err!=null){\n                    button.setText("Update check failed — retry");\n                    button.setOnAction(e->checkForUpdates(button,true));\n                    if(manual)new Alert(Alert.AlertType.ERROR,"Could not check for updates: "+message(unwrap(err))).showAndWait();\n                    return;\n                }\n                if(info.updateAvailable()){\n                    button.setText("Update v"+info.latestVersion());\n                    button.setOnAction(e->installUpdate(info,button));\n                }else{\n                    button.setText("Up to date");\n                    button.setOnAction(e->checkForUpdates(button,true));\n                }\n            }));\n    }\n'''
if old_method not in s: raise SystemExit('checkForUpdates method not found')
s=s.replace(old_method,new_method)
p.write_text(s)
